-- ROCK9086 pass 15 (generated by gen_020.py): rows production logged under Fluid verification 2026-10-12..11-03.
-- Same output on DotLiquid:
--   pageparam-quotes (HtmlContent 443 / 445, Camp App pages 1078 / 1079): `id:'{{PageParameter['parameter']}}'`
--     nests single quotes in an entity-command parameter; Fluid fails the block. Assign the parameter first.
--   string-vs-bool (Block 8594 FormattedOutput, Camp FA totals page 4429): `isPublic == true` on a RawValue string;
--     Fluid treats 'False' == true as true and shows non-public campuses. Compare to 'True'. LavaProbe B1/B2.
-- Guarded REPLACE per row, @DryRun = 1 rolls back, the live run is all-or-nothing, one backup per row to
-- dbo._ROCK9086_LavaBackup, rows absent from the target database log -1. Clear the Rock cache after.
SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
DECLARE @DryRun bit = 1;
DECLARE @log TABLE (Tbl sysname, Id int, FixRule varchar(40), [Rows] int);
DECLARE @avkeys TABLE (Id int, AttributeId int, EntityId int);
INSERT @avkeys VALUES (257771129, 1201, 8594);
BEGIN TRAN;

IF OBJECT_ID('dbo._ROCK9086_LavaBackup') IS NULL
    CREATE TABLE dbo._ROCK9086_LavaBackup (Tbl sysname NOT NULL, Id int NOT NULL, Col sysname NOT NULL, OldValue nvarchar(max) NULL, BackedUpAt datetime NOT NULL DEFAULT GETDATE());

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'HtmlContent', x.[Id], 'Content', x.[Content] FROM [HtmlContent] x WHERE x.[Id] = 443
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'HtmlContent' AND b.Id = x.[Id] AND b.Col = 'Content');
UPDATE [HtmlContent] SET [Content] = REPLACE([Content], N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}', N'{%- assign itemId = ''Global'' | PageParameter:''parameter'' -%}{%- contentchannelitem id:''{{ itemId }}'' %}')
WHERE [Id] = 443
  AND (DATALENGTH([Content]) - DATALENGTH(REPLACE([Content], N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}', N''))) / DATALENGTH(N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}') = 1
  AND [Version] = (SELECT MAX([Version]) FROM HtmlContent h2 WHERE h2.BlockId = HtmlContent.BlockId);
INSERT @log VALUES ('HtmlContent', 443, 'pageparam-quotes', @@ROWCOUNT);

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'HtmlContent', x.[Id], 'Content', x.[Content] FROM [HtmlContent] x WHERE x.[Id] = 445
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'HtmlContent' AND b.Id = x.[Id] AND b.Col = 'Content');
UPDATE [HtmlContent] SET [Content] = REPLACE([Content], N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}', N'{%- assign itemId = ''Global'' | PageParameter:''parameter'' -%}{%- contentchannelitem id:''{{ itemId }}'' %}')
WHERE [Id] = 445
  AND (DATALENGTH([Content]) - DATALENGTH(REPLACE([Content], N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}', N''))) / DATALENGTH(N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}') = 1
  AND [Version] = (SELECT MAX([Version]) FROM HtmlContent h2 WHERE h2.BlockId = HtmlContent.BlockId);
INSERT @log VALUES ('HtmlContent', 445, 'pageparam-quotes', @@ROWCOUNT);

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'AttributeValue', x.[Id], 'Value', x.[Value] FROM [AttributeValue] x WHERE x.[Id] = 257771129 AND x.[AttributeId] = 1201 AND x.[EntityId] = 8594
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'AttributeValue' AND b.Id = x.[Id] AND b.Col = 'Value');
UPDATE [AttributeValue] SET [Value] = REPLACE([Value], N'{%if campus.IsActive == true and isPublic == true %}', N'{%if campus.IsActive == true and isPublic == ''True'' %}')
WHERE [Id] = 257771129 AND [AttributeId] = 1201 AND [EntityId] = 8594
  AND (DATALENGTH([Value]) - DATALENGTH(REPLACE([Value], N'{%if campus.IsActive == true and isPublic == true %}', N''))) / DATALENGTH(N'{%if campus.IsActive == true and isPublic == true %}') = 1;
INSERT @log VALUES ('AttributeValue', 257771129, 'string-vs-bool', @@ROWCOUNT);

UPDATE l SET [Rows] = -1 FROM @log l WHERE l.[Rows] = 0 AND NOT EXISTS (
    SELECT 1 FROM WorkflowType x WHERE l.Tbl = 'WorkflowType' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM HtmlContent x WHERE l.Tbl = 'HtmlContent' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM WorkflowActionForm x WHERE l.Tbl = 'WorkflowActionForm' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM SystemCommunication x WHERE l.Tbl = 'SystemCommunication' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM Block x WHERE l.Tbl = 'Block' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM ReportField x WHERE l.Tbl = 'ReportField' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM AttributeValue x JOIN @avkeys k ON k.Id = x.Id AND k.AttributeId = x.AttributeId AND k.EntityId = x.EntityId
        WHERE l.Tbl = 'AttributeValue' AND x.Id = l.Id);
SELECT * FROM @log ORDER BY Tbl, Id;
IF EXISTS (SELECT 1 FROM @log WHERE [Rows] NOT IN (1, -1)) PRINT 'WARNING: some statements did not update exactly one row - review before committing.';
IF @DryRun = 0 AND EXISTS (SELECT 1 FROM @log WHERE [Rows] NOT IN (1, -1))
BEGIN ROLLBACK; THROW 50000, 'ROCK9086 pass 15: a guarded update did not match exactly one row; nothing committed.', 1; END

SELECT 'HtmlContent' Tbl, 443 Id, CASE WHEN CHARINDEX(N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}' COLLATE Latin1_General_CS_AS, [Content] COLLATE Latin1_General_CS_AS) > 0 THEN 1 ELSE 0 END StillOld FROM [HtmlContent] WHERE [Id] = 443
UNION ALL
SELECT 'HtmlContent' Tbl, 445 Id, CASE WHEN CHARINDEX(N'{%- contentchannelitem id:''{{PageParameter[''parameter'']}}'' %}' COLLATE Latin1_General_CS_AS, [Content] COLLATE Latin1_General_CS_AS) > 0 THEN 1 ELSE 0 END StillOld FROM [HtmlContent] WHERE [Id] = 445
UNION ALL
SELECT 'AttributeValue' Tbl, 257771129 Id, CASE WHEN CHARINDEX(N'{%if campus.IsActive == true and isPublic == true %}' COLLATE Latin1_General_CS_AS, [Value] COLLATE Latin1_General_CS_AS) > 0 THEN 1 ELSE 0 END StillOld FROM [AttributeValue] WHERE [Id] = 257771129;

IF @DryRun = 1 BEGIN ROLLBACK; PRINT 'Dry run - rolled back.'; END ELSE BEGIN COMMIT; PRINT 'Committed. Now clear the Rock cache.'; END
